// Data-driven card -> cast animation + visual map (data/fx/anim.json), layered on the real spell art (data/fx/real.json).
//   schools : school -> hero windup + the school-tinted FLOOR flare sheet (a card whose real art is partial/missing is never silent)
//   cards   : card id -> { cls, school, anim, rel, art, floor }   GENERATED by tools/spires/build-anim-map.mjs for every card
//   overrides: hand-tuned per-card fields merged over the generated row ({ rel, school, floor, anim })
// anim kinds: melee (hero lunges, Attack clip), cast (planted, Precast+Cast clips, missile leaves on the release frame),
//             gesture (self / group spells: Cast clip, aura or impact on the target).
// `rel` = seconds from cast start to the RELEASE frame; the missile leaves / the impact lands relative to it, and the
// damage number is released at the impact (fx onImpact), so cast -> travel -> impact -> number stays in order.
// Pure data + lookups, no DOM / GL. realplay.js, choreo.js and combatDirector.js ask; nothing else knows the table layout.
import { elementFor, kindFor } from "./elements.js?v=20261029d";

const DEFAULT_SCHOOL = { sheet: "impact_burst", cell: "star", windup: 0.2, selfSheet: "buff_glyph_rise" };
/** seconds to the release frame per anim kind. actors3d.js CAST_RELEASE_MS / gesture timing is tuned to these. */
export const RELEASE = { melee: 0.15, cast: 0.4, gesture: 0.32 };
export const CLIPS = { melee: ["attack"], cast: ["precast", "cast"], gesture: ["cast"] };

/** Pure resolver: a card definition -> animation row. `ranged` comes from combatDirector.isCardRanged, `entry` from real.json. */
export function resolveAnim(card, classId, { ranged = false, entry = null } = {}) {
  const school = elementFor(card, classId), kind = kindFor(card);
  const anim = kind === "attack" ? (ranged ? "cast" : "melee") : "gesture";
  const roles = entry && entry.roles ? Object.keys(entry.roles).filter((k) => entry.roles[k] && entry.roles[k].length) : [];
  const landing = roles.includes("impact") || roles.includes("aura");
  const art = !roles.length ? "school" : (landing && (kind !== "attack" || !ranged || roles.includes("missile")) ? "real" : "partial");
  return { id: card && card.id, cls: classId, school, kind, anim, rel: RELEASE[anim], art, floor: art !== "real" };
}

export function createAnimMap({ root, v = "" } = {}) {
  root = root || new URL("../../", import.meta.url).href;
  let data = { schools: {}, cards: {}, overrides: {} };
  const ready = fetch(root + "data/fx/anim.json" + (v ? "?v=" + v : "")).then((r) => (r.ok ? r.json() : null))
    .then((j) => { if (j && j.schools) data = { overrides: {}, cards: {}, ...j }; return api; }).catch(() => api);
  const school = (el) => data.schools[el] || DEFAULT_SCHOOL;
  const api = {
    ready,
    school,
    /** merged row for a card id (generated + override), or null */
    card: (id) => (id && (data.cards[id] || data.overrides[id]) ? { ...(data.cards[id] || {}), ...(data.overrides[id] || {}) } : null),
    /** seconds from cast start to the release frame (missile leaves / impact base). Falls back to the anim-kind table. */
    release(id, animKind) {
      const c = api.card(id); if (c && typeof c.rel === "number") return c.rel;
      return RELEASE[animKind] != null ? RELEASE[animKind] : RELEASE.gesture;
    },
    /** seconds of hero windup before the missile leaves / the impact lands (per-school fallback) */
    windup(id, el, fallback) {
      const c = api.card(id); if (c && typeof c.windup === "number") return c.windup;
      const s = school(el); return typeof s.windup === "number" ? s.windup : fallback;
    },
    /** does this card get the guaranteed school-tinted floor flare? Cards with no real art always do. */
    needsFloor(id, hasReal) { const c = api.card(id); return !hasReal || !!(c && c.floor); },
  };
  return api;
}
